nsresult ExchangeFolder::HandleDeleteOperation(
    bool forceHardDelete, std::function<nsresult()>&& onHardDelete,
    std::function<nsresult(IExchangeFolder*)>&& onSoftDelete) {
  using DeleteModel = IExchangeIncomingServer::DeleteModel;

  nsresult rv;

  // If any ancestor of this folder is the trash folder, then hard delete.
  bool isInTrashFolder = false;
  nsCOMPtr<nsIMsgFolder> folder = this;
  while (folder) {
    bool isTrashFolder = false;
    MOZ_TRY(folder->GetFlag(nsMsgFolderFlags::Trash, &isTrashFolder));
    if (isTrashFolder) {
      isInTrashFolder = true;
      break;
    }
    folder->GetParent(getter_AddRefs(folder));
  }

  // Check the delete model to see if this should be a permanent delete.
  nsCOMPtr<nsIMsgIncomingServer> server;
  rv = GetServer(getter_AddRefs(server));
  NS_ENSURE_SUCCESS(rv, rv);
  nsCOMPtr<IExchangeIncomingServer> exchangeServer{
      do_QueryInterface(server, &rv)};
  NS_ENSURE_SUCCESS(rv, rv);

  DeleteModel deleteModel;
  rv = exchangeServer->GetDeleteModel(&deleteModel);

  if (forceHardDelete || isInTrashFolder ||
      deleteModel == DeleteModel::PERMANENTLY_DELETE) {
    return onHardDelete();
  }

  // We're moving the messages to trash folder.
  nsCOMPtr<nsIMsgFolder> trashFolder;
  rv = GetTrashFolder(getter_AddRefs(trashFolder));
  NS_ENSURE_SUCCESS(rv, rv);

  if (!trashFolder) {
    return NS_ERROR_UNEXPECTED;
  }

  nsCOMPtr<IExchangeFolder> exchangeTrashFolder =
      do_QueryInterface(trashFolder, &rv);
  NS_ENSURE_SUCCESS(rv, rv);

  return onSoftDelete(exchangeTrashFolder);

// We're moving the messages to trash folder.
const auto onSoftDelete =
    [self = RefPtr(this), headers, window = RefPtr(aMsgWindow),
     copyListener = RefPtr(aCopyListener)](IExchangeFolder* trashFolder) {
      return trashFolder->CopyItemsOnSameServer(
          self, headers, true, window, copyListener, true,
          nsIMessenger::eDeleteMsg, nullptr);
    };

return HandleDeleteOperation(aDeleteStorage, std::move(onHardDelete),
                             std::move(onSoftDelete));

// By default, the delete model should be move to trash, and the folder should
// be the distinguished folder we got from the server.
Assert.equal(
  ewsIncomingServer.deleteModel,
  Ci.IExchangeIncomingServer.MOVE_TO_TRASH,
  "Default delete model should be move to trash"
);
Assert.equal(
  ewsIncomingServer.trashFolderPath,
  "Deleted Items",
  "trash folder path should be 'Deleted Items'"
);

Assert.ok(
  !!(deletedItemsFolder.flags & Ci.nsMsgFolderFlags.Trash),
  "Deleted Items should have the trash flag."

// Create a new folder to use as trash.
ewsServer.appendRemoteFolder(
  new RemoteFolder("delete2", "root", "delete2", "delete2")
);

await syncFolder(incomingServer, rootFolder);

const newDeleteFolder = rootFolder.getChildNamed("delete2");
Assert.ok(!!newDeleteFolder, "New delete folder should exist.");

ewsIncomingServer.trashFolderPath = "delete2";
Assert.ok(
  newDeleteFolder.getFlag(Ci.nsMsgFolderFlags.Trash),
  "New delete folder should now have the Trash flag."
);
Assert.equal(
  ewsIncomingServer.trashFolderPath,
  "delete2",
  "Incoming server preference should have been updated."
);

const headersToDelete2 = [[...inboxFolder.messages][0]];

await deleteItems(inboxFolder, headersToDelete2);

Assert.equal(
  inboxFolder.getTotalMessages(false),
  1,
  "Inbox should have 1 message."
);
Assert.equal(
  newDeleteFolder.getTotalMessages(false),
  1,
  "New trash folder should have 1 message."
);

ewsIncomingServer.deleteModel = Ci.IExchangeIncomingServer.DELETE_PERMANENTLY;

const headersToDelete3 = [[...inboxFolder.messages][0]];

await deleteItems(inboxFolder, headersToDelete3);

Assert.equal(
  inboxFolder.getTotalMessages(false),
  0,
  "Should have reached inbox zero."
);

// Make sure the two delete folders we used in this test still only have one
// message each.
Assert.equal(
  deletedItemsFolder.getTotalMessages(false),
  1,
  "Deleted Items should have 1 message."
);
Assert.equal(
  newDeleteFolder.getTotalMessages(false),
  1,
  "delete2 should have 1 message."
